-- ============================================
-- SPU产品主表 (products_spu_v3)
-- ============================================

DROP TABLE IF EXISTS `products_spu_v3`;
CREATE TABLE `products_spu_v3` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `brand` varchar(50) NOT NULL COMMENT '品牌',
  `model_name` varchar(200) NOT NULL COMMENT '型号名称',
  `category` varchar(50) DEFAULT 'phone' COMMENT '分类',
  `image_url` varchar(500) DEFAULT NULL COMMENT '主图URL',
  `min_price` decimal(10,2) DEFAULT 0 COMMENT '最低价',
  `max_price` decimal(10,2) DEFAULT 0 COMMENT '最高价',
  `sku_count` int(11) DEFAULT 0 COMMENT 'SKU数量',
  `gallery_images` text COMMENT '图片集JSON',
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_brand` (`brand`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SPU产品主表';

-- SPU产品数据

-- ============================================
-- SKU变体表 (products_sku_v3)
-- ============================================

DROP TABLE IF EXISTS `products_sku_v3`;
CREATE TABLE `products_sku_v3` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `spu_id` int(11) NOT NULL COMMENT '关联SPU ID',
  `full_name` varchar(300) NOT NULL COMMENT '完整名称',
  `color` varchar(50) DEFAULT NULL COMMENT '颜色',
  `storage` varchar(50) DEFAULT NULL COMMENT '存储容量',
  `price` decimal(10,2) NOT NULL COMMENT '批发价',
  `official_price` decimal(10,2) DEFAULT 0 COMMENT '官网价',
  `stock_status` varchar(20) DEFAULT 'in_stock' COMMENT '库存状态',
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_spu_id` (`spu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU变体表';

